use hec_native_ic::{counted,fp::Fp,poly::Poly,instance::pick_instance,oracle::{split,OracleStats}};
fn mul(a:&Poly,b:&Poly,f:&Fp)->Poly{a.mul(b,f)}
fn square(a:&Poly,f:&Fp)->Poly{a.mul(a,f)}
fn scale(a:&Poly,k:i64,f:&Fp)->Poly{a.scale(f.from_i64(k),f)}
fn det(m:[[Poly;3];3],f:&Fp)->Poly{let mut out=Poly::zero();for p in [[0,1,2],[1,2,0],[2,0,1]]{out=out.add(&m[0][p[0]].mul(&m[1][p[1]],f).mul(&m[2][p[2]],f),f);}for p in [[0,2,1],[2,1,0],[1,0,2]]{out=out.sub(&m[0][p[0]].mul(&m[1][p[1]],f).mul(&m[2][p[2]],f),f);}out}
fn remainder(source:&Poly,g:&[Poly;3],f:&Fp)->[Poly;3]{let mut a=[Poly::zero();3];for i in(0..source.n).rev(){a=[scale(&a[2].mul(&g[0],f),-1,f),a[0].sub(&a[2].mul(&g[1],f),f),a[1].sub(&a[2].mul(&g[2],f),f)];a[0]=a[0].add(&Poly::constant(source.c[i]),f);}a}
fn norm(a:&[Poly;3],g:&[Poly;3],f:&Fp)->Poly{let c0=*a;let c1=[scale(&a[2].mul(&g[0],f),-1,f),a[0].sub(&a[2].mul(&g[1],f),f),a[1].sub(&a[2].mul(&g[2],f),f)];let c2=[scale(&c1[2].mul(&g[0],f),-1,f),c1[0].sub(&c1[2].mul(&g[1],f),f),c1[1].sub(&c1[2].mul(&g[2],f),f)];det([[c0[0],c1[0],c2[0]],[c0[1],c1[1],c2[1]],[c0[2],c1[2],c2[2]]],f)}
fn sqrt_monic(s:&Poly,f:&Fp)->Poly{assert!(!s.is_zero());assert_eq!(s.deg()%2,0);let n=s.deg()as usize/2;let mut h=Poly::zero();h.n=n+1;h.c[n]=1;let inv2=f.inv(2);for i in(0..n).rev(){let known=h.mul(&h,f).c[n+i];h.c[i]=f.mul(f.sub(s.c[n+i],known),inv2);}assert_eq!(h.mul(&h,f),*s);h}
fn key<'a>(l:&'a str,k:&str)->Option<&'a str>{l.split_whitespace().find_map(|s|s.strip_prefix(&format!("{k}=")))}
fn array(l:&str,k:&str)->Poly{let text=l.split(&format!("{k}=[")).nth(1).unwrap().split(']').next().unwrap();Poly::from_coeffs(&text.split(',').map(|s|s.trim().parse().unwrap()).collect::<Vec<u64>>())}
fn coeff(p:&Poly)->Vec<u64>{p.c[..p.n].to_vec()}
fn main(){counted::disable();let raw=include_str!("../native-trigonal-map/CONTROL.txt");let mut maps=0;let mut rational=0;let mut checked_points=0;for l in raw.lines().filter(|l|l.starts_with("MAP ")){let p:u64=key(l,"p").unwrap().parse().unwrap();let inst=pick_instance(p,3).unwrap();assert_eq!(inst.c.to_string(),key(l,"c").unwrap());let f=&inst.curve.fp;let n0=array(l,"numerator");let d0=array(l,"denominator");let z=f.sub(f.mul(n0.c[3],d0.c[2]),f.mul(n0.c[2],d0.c[3]));assert_ne!(z,0);let iz=f.inv(z);let n=n0.scale(d0.c[2],f).sub(&d0.scale(n0.c[2],f),f).scale(iz,f);let d=d0.scale(n0.c[3],f).sub(&n0.scale(d0.c[3],f),f).scale(iz,f);assert_eq!(n.c[3],1);assert_eq!(n.c[2],0);assert_eq!(d.deg(),2);assert_eq!(d.c[2],1);assert_eq!(Poly::gcd(&n,&d,f).deg(),0);
let g=[Poly::from_coeffs(&[n.c[0],f.neg(d.c[0])]),Poly::from_coeffs(&[n.c[1],f.neg(d.c[1])]),Poly::from_coeffs(&[0,f.neg(1)])];let a=remainder(&inst.curve.f,&g,f);let s=norm(&a,&g,f);assert_eq!(s.deg(),6);let lead=s.lc();let sm=s.scale(f.inv(lead),f);let root=sqrt_monic(&sm,f);assert_eq!(root.deg(),3);assert_eq!(Poly::gcd(&root,&root.deriv(f),f).deg(),0);let eta=(2..p).find(|&x|f.legendre(x)==-1).unwrap();assert_eq!(f.legendre(f.mul(f.mul(eta,eta),f.mul(eta,lead))),-f.legendre(lead));let root_fp=f.sqrt(lead).map(|v|root.scale(v,f));if let Some(r)=root_fp{assert_eq!(square(&r,f),s);rational+=1;}
let g0=g[0];let g1=g[1];let g2=g[2];let f0=a[0];let f1=a[1];let f2=a[2];let delta4=scale(&square(&g0,f),-27,f).add(&scale(&g0.mul(&g1,f).mul(&g2,f),18,f),f).sub(&scale(&g0.mul(&g2,f).mul(&g2,f).mul(&g2,f),4,f),f).sub(&scale(&g1.mul(&g1,f).mul(&g1,f),4,f),f).add(&square(&g1,f).mul(&square(&g2,f),f),f);
let delta2=scale(&f0.mul(&g1,f),12,f).sub(&scale(&f0.mul(&square(&g2,f),f),4,f),f).sub(&scale(&f1.mul(&g0,f),18,f),f).add(&scale(&f1.mul(&g1,f).mul(&g2,f),2,f),f).add(&scale(&f2.mul(&g0,f).mul(&g2,f),12,f),f).sub(&scale(&f2.mul(&square(&g1,f),f),4,f),f);let delta0=square(&f1,f).sub(&scale(&f0.mul(&f2,f),4,f),f);let delta1_squared=scale(&s,64,f);
let quartic=[square(&delta0,f),scale(&delta2.mul(&delta0,f),2,f).sub(&delta1_squared,f),square(&delta2,f).add(&scale(&delta4.mul(&delta0,f),2,f),f),scale(&delta4.mul(&delta2,f),2,f),square(&delta4,f)];let mut split_fibres=0;let mut common_fibres=0;let mut fibre_points=0;let mut correspondence_checks=0;
for t in 0..p{let gv=[g0.eval(t,f),g1.eval(t,f),g2.eval(t,f)];let gt=Poly::from_coeffs(&[gv[0],gv[1],gv[2],1]);let av=[f0.eval(t,f),f1.eval(t,f),f2.eval(t,f)];assert_eq!(inst.curve.f.rem(&gt,f),Poly::from_coeffs(&av));assert_eq!(s.eval(t,f),Poly::resultant(&gt,&inst.curve.f,f));assert_eq!(delta4.eval(t,f),gt.disc_monic(f));let ds=[delta0.eval(t,f),delta2.eval(t,f),delta4.eval(t,f)];if ds[0]==0||ds[2]==0||s.eval(t,f)==0{continue;}let Some(roots)=split(&gt,f,&mut OracleStats::default())else{continue;};assert_eq!(roots.as_slice().len(),3);assert!(roots.as_slice().iter().all(|r|r.1==1));split_fibres+=1;let xs:Vec<_>=roots.as_slice().iter().map(|r|r.0).collect();let vals:Vec<_>=xs.iter().map(|&x|inst.curve.f.eval(x,f)).collect();let classes:Vec<_>=vals.iter().map(|&v|f.legendre(v)).collect();if classes.iter().any(|&v|v!=classes[0]){continue;}assert!(classes[0]!=0);let e=if classes[0]==1{1}else{eta};let ie=f.inv(e);let ys:Vec<_>=vals.iter().map(|&v|f.sqrt(f.mul(v,ie)).unwrap()).collect();common_fibres+=1;let mut seen=std::collections::BTreeSet::new();for signs in 0..4{let mut b=Poly::zero();for i in 0..3{let q=gt.div_exact(&Poly::x_minus(xs[i],f),f);let y=if i>0&&((signs>>(i-1))&1)!=0{f.neg(ys[i])}else{ys[i]};let scale=f.mul(y,f.inv(q.eval(xs[i],f)));b=b.add(&q.scale(scale,f),f);}assert_eq!(b.mulmod(&b,&gt,f).scale(e,f),Poly::from_coeffs(&av));let z=[f.mul(e,f.mul(b.c[0],b.c[0])),f.mul(e,f.mul(b.c[0],b.c[1])),f.mul(e,f.mul(b.c[0],b.c[2])),f.mul(e,f.mul(b.c[1],b.c[1])),f.mul(e,f.mul(b.c[1],b.c[2])),f.mul(e,f.mul(b.c[2],b.c[2]))];assert!(seen.insert(z));assert_eq!(f.sub(f.mul(z[1],z[1]),f.mul(z[0],z[3])),0);assert_eq!(f.sub(f.mul(z[1],z[2]),f.mul(z[0],z[4])),0);assert_eq!(f.sub(f.mul(z[2],z[2]),f.mul(z[0],z[5])),0);assert_eq!(f.sub(f.mul(z[2],z[3]),f.mul(z[1],z[4])),0);assert_eq!(f.sub(f.mul(z[2],z[4]),f.mul(z[1],z[5])),0);assert_eq!(f.sub(f.mul(z[4],z[4]),f.mul(z[3],z[5])),0);
let c0=f.sub(f.add(f.sub(f.mul(f.mul(gv[2],gv[0]),z[5]),f.mul(f.mul(2,gv[0]),z[4])),z[0]),av[0]);let c1=f.sub(f.add(f.sub(f.mul(f.sub(f.mul(gv[2],gv[1]),gv[0]),z[5]),f.mul(f.mul(2,gv[1]),z[4])),f.mul(2,z[1])),av[1]);let c2=f.sub(f.add(f.add(f.sub(f.mul(f.sub(f.mul(gv[2],gv[2]),gv[1]),z[5]),f.mul(f.mul(2,gv[2]),z[4])),f.mul(2,z[2])),z[3]),av[2]);assert_eq!([c0,c1,c2],[0;3]);let lhs=quartic.iter().rev().fold(0,|acc,q|f.add(f.mul(acc,z[5]),q.eval(t,f)));assert_eq!(lhs,0);if let Some(rs)=root_fp{let delta1=f.mul(8,rs.eval(t,f));let top=f.add(f.add(f.mul(ds[2],f.mul(z[5],z[5])),f.mul(ds[1],z[5])),ds[0]);let rho=f.mul(top,f.inv(delta1));assert_eq!(f.mul(rho,rho),z[5]);assert_ne!(rho,0);let ir=f.inv(rho);let recovered=Poly::from_coeffs(&[f.mul(z[2],ir),f.mul(z[4],ir),f.mul(z[5],ir)]);assert_eq!(recovered.mulmod(&recovered,&gt,f),Poly::from_coeffs(&av));correspondence_checks+=1;}fibre_points+=1;}assert_eq!(seen.len(),4);}maps+=1;checked_points+=fibre_points;
println!("MAP p={p} c={} normalized_n={:?} normalized_d={:?} f_remainder={:?} norm_s={:?} norm_scalar={lead} norm_square_class={} monic_square_root={:?} rational_correspondence_square_test={} split_safe_fibres={split_fibres} common_class_fibres={common_fibres} checked_quotient_points={fibre_points} rational_correspondence_checks={correspondence_checks}",inst.c,coeff(&n),coeff(&d),a.iter().map(coeff).collect::<Vec<_>>(),coeff(&s),f.legendre(lead),coeff(&root),root_fp.is_some());println!("AFFINE p={p} normalized_n={:?} delta0={:?} delta2={:?} delta4={:?} delta1_squared={:?} b22_quartic_coefficients={:?}",coeff(&n),coeff(&delta0),coeff(&delta2),coeff(&delta4),coeff(&delta1_squared),quartic.iter().map(coeff).collect::<Vec<_>>());}
assert_eq!(maps,6);eprintln!("PASS maps=6 rational_correspondence_square_tests={rational} checked_quotient_fibre_points={checked_points} normalized_maps=true all_base_t_resultants=true norm_square_up_to_scalar=true twist_control=true no_smooth_model_or_isogeny_action_or_speed_claim=true");}
